-- Glossary covers: the cover photos Yasmim set on each Notion page.
-- Every card's cover is replaced; a card with no Notion cover has none (covers are optional).
-- Safe to run more than once. Covers set later on the site would be replaced if it runs again.

alter table public.concha_terms add column if not exists cover_position text not null default 'center 50%'
  check (cover_position ~ '^center [0-9]{1,3}%$');

drop table if exists cover_import;
create temp table cover_import (term text, slug text, image_url text, pos text);

update public.concha_terms set image_url = '', cover_position = 'center 50%' where kind = 'glossary';

update public.concha_terms c
   set image_url = g.image_url, cover_position = g.pos
  from cover_import g
 where c.kind = 'glossary'
   and (c.slug = g.slug or lower(public.unaccent_simple(c.term)) = lower(public.unaccent_simple(g.term))
        or (char_length(g.term) >= 40 and replace(public.term_slug(c.term), '-', '') like replace(public.term_slug(g.term), '-', '') || '%')
        or (char_length(c.term) >= 40 and replace(public.term_slug(g.term), '-', '') like replace(public.term_slug(c.term), '-', '') || '%'));

drop table cover_import;
